package com.crypto.laplace.scheduler;
import static org.mockito.Mockito.*;import com.crypto.domain.model.Kline;import com.crypto.laplace.execution.LaplacePaperExecutionService;import com.crypto.laplace.model.LaplacePositionStatus;import com.crypto.laplace.persistence.*;import com.crypto.laplace.service.*;import java.time.Instant;import java.util.List;import org.junit.jupiter.api.Test;
class LaplaceStopLossFanOutSchedulerTest {
 @Test void loadsOneCandleForTrueOnly(){var gate=mock(LaplaceMarketDataGate.class);var runtime=mock(LaplaceRuntimeService.class);var positions=mock(LaplacePaperPositionRepository.class);var klines=mock(FiveMinuteKlineService.class);var evaluator=mock(LaplaceStopLossScheduler.class);when(gate.allowsMarketData()).thenReturn(true);when(runtime.isActive()).thenReturn(true);var position=LaplacePaperPositionEntity.builder().id("t").symbol("BTCUSDT").build();when(positions.findByStrategyAndStatus(LaplacePaperExecutionService.STRATEGY,LaplacePositionStatus.OPEN)).thenReturn(List.of(position));var candle=Kline.builder().closeTime(Instant.parse("2026-08-14T00:04:59Z")).build();when(klines.loadLatestClosed("BTCUSDT")).thenReturn(candle);new LaplaceStopLossFanOutScheduler(gate,runtime,positions,klines,evaluator).evaluate();verify(klines).loadLatestClosed("BTCUSDT");verify(evaluator).evaluate("t","BTCUSDT",same(candle));}
}
